// Filter out header rows and clean data
const items = $input.all();
const cleanedItems = [];

// Function to format time to readable format
function formatTime(timeString) {
  if (!timeString || timeString === 'NaN' || timeString === '') {
    return '';
  }

  try {
    // Try to parse ISO 8601 format (e.g., "2026-01-01T12:25:19.000+00:00")
    const date = new Date(timeString);

    // Check if date is valid
    if (isNaN(date.getTime())) {
      return timeString; // Return original if can't parse
    }

    // Format as HH:MM:SS AM/PM (12-hour format)
    let hours = date.getHours();
    const minutes = date.getMinutes().toString().padStart(2, '0');
    const seconds = date.getSeconds().toString().padStart(2, '0');
    const ampm = hours >= 12 ? 'PM' : 'AM';
    hours = hours % 12;
    hours = hours ? hours : 12; // 0 should be 12
    hours = hours.toString().padStart(2, '0');

    return `${hours}:${minutes}:${seconds} ${ampm}`;
  } catch (e) {
    // If parsing fails, return original string
    return timeString;
  }
}

// Function to format date (YYYY-MM-DD)
function formatDate(dateString) {
  if (!dateString || dateString === 'NaN' || dateString === '') {
    return '';
  }

  try {
    const date = new Date(dateString);

    // Check if date is valid
    if (isNaN(date.getTime())) {
      return dateString; // Return original if can't parse
    }

    // Format date as YYYY-MM-DD
    const year = date.getFullYear();
    const month = (date.getMonth() + 1).toString().padStart(2, '0');
    const day = date.getDate().toString().padStart(2, '0');

    return `${year}-${month}-${day}`;
  } catch (e) {
    // If parsing fails, return original string
    return dateString;
  }
}

// Function to get day of week
function getDayOfWeek(dateString) {
  if (!dateString || dateString === 'NaN' || dateString === '') {
    return '';
  }

  try {
    const date = new Date(dateString);

    // Check if date is valid
    if (isNaN(date.getTime())) {
      return '';
    }

    // Get day of week
    const daysOfWeek = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
    return daysOfWeek[date.getDay()];
  } catch (e) {
    return '';
  }
}

// Function to extract employee name from Commissions field
function extractEmployeeFromCommissions(commissionsString) {
  if (!commissionsString || commissionsString === 'NaN' || commissionsString === '') {
    return '';
  }

  // Commissions format is like "Esmaya: -130" or "Esmaya Purcell: -130"
  // Extract the part before the colon
  const colonIndex = commissionsString.indexOf(':');
  if (colonIndex > 0) {
    return commissionsString.substring(0, colonIndex).trim();
  }

  return commissionsString.trim();
}

for (const item of items) {
  const json = item.json;

  // Skip rows that don't have a valid Trans # (header rows)
  if (json['Trans #'] && json['Trans #'] !== 'NaN' && json['Trans #'] !== '') {
    // Parse Gross Sales
    const grossSales = json['Gross Sales'] ? parseFloat(String(json['Gross Sales']).replace(/[^0-9.-]/g, '')) || 0 : 0;

    // Separate refunds from gross sales
    let refunds = null;
    let finalGrossSales = grossSales;
    let employee = json['Employee'] || '';
    let commissions = json['Commissions'] || '';

    // If Gross Sales is negative, move it to Refunds
    if (grossSales < 0) {
      refunds = grossSales; // Keep as negative value
      finalGrossSales = 0; // Set Gross Sales to 0

      // For refunds, extract employee name from Commissions and use it for both fields
      const employeeFromCommissions = extractEmployeeFromCommissions(commissions);
      if (employeeFromCommissions) {
        employee = employeeFromCommissions;
        commissions = employeeFromCommissions;
      }
    }

    // Clean and transform the data
    const cleanedItem = {
      json: {
        'Trans #': json['Trans #'] || '',
        'Customer': json['Customer'] || '(N/A)',
        'Date': formatDate(json['Date']),
        'Day of the Week': getDayOfWeek(json['Date']),
        'Time': formatTime(json['Time']),
        'Net Sales': json['Net Sales'] ? parseFloat(String(json['Net Sales']).replace(/[^0-9.-]/g, '')) || 0 : 0,
        'Gross Sales': finalGrossSales,
        'Employee': employee,
        'Commissions': commissions,
        'Products': json['Products'] || ''
      }
    };

    // Only add Refunds field if there's an actual refund value
    if (refunds !== null && refunds < 0) {
      cleanedItem.json['Refunds'] = refunds;
    }

    cleanedItems.push(cleanedItem);
  }
}

return cleanedItems;
